import{_ as t,o as a,c as o,a0 as i}from"./chunks/framework.BhkMvQqH.js";const p=JSON.parse('{"title":"Auth & Onboarding Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specs/auth-onboarding.md","filePath":"specs/auth-onboarding.md"}'),r={name:"specs/auth-onboarding.md"};function d(n,e,s,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="auth-onboarding-specification" tabindex="-1">Auth &amp; Onboarding Specification <a class="header-anchor" href="#auth-onboarding-specification" aria-label="Permalink to &quot;Auth &amp; Onboarding Specification&quot;">​</a></h1><h2 id="screen-login" tabindex="-1">Screen: Login <a class="header-anchor" href="#screen-login" aria-label="Permalink to &quot;Screen: Login&quot;">​</a></h2><h3 id="route" tabindex="-1">Route <a class="header-anchor" href="#route" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/login</code></p><h3 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Authenticate user via email magic link, password, or OAuth provider.</p><h3 id="data-source" tabindex="-1">Data Source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: Supabase Auth → <code>auth.users</code> → triggers <code>handle_new_user()</code> → <code>User</code>, <code>UserPreference</code></li><li><strong>RLS Context</strong>: Pre-tenant (public). No tenant context required.</li></ul><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Email</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td>RFC 5322 validated</td></tr><tr><td>Password</td><td>password</td><td>User input</td><td>Conditional</td><td>Yes</td><td>Required only if email auth mode; min 8 chars</td></tr><tr><td>OAuth Buttons</td><td>button group</td><td>Provider config</td><td>No</td><td>N/A</td><td>Google, etc. — configurable per deployment</td></tr></tbody></table><h3 id="actions-crud" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[ ] Create</li><li>[ ] Read</li><li>[ ] Update</li><li>[ ] Delete</li><li>[x] Special: Authenticate via Supabase Auth (<code>signInWithOtp</code>, <code>signInWithPassword</code>, <code>signInWithOAuth</code>)</li></ul><h3 id="related-selectors-modals" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li>None</li></ul><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>AUTH</code></li><li><strong>Minimum role permissions</strong>: None (public)</li><li><strong>Special rules</strong>: Redirect to Tenant Switcher if user belongs to &gt;1 org; redirect to Dashboard if single org.</li></ul><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: None (standalone landing)</li><li><strong>Links to</strong>: Tenant Switcher or Dashboard (post-login)</li></ul><h3 id="ux-pattern" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Form / Landing page</p><h3 id="business-rules-validations" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>Email format MUST be RFC 5322 compliant</li><li>Password MUST be &gt;= 8 characters when using email auth</li><li>After successful login, MUST redirect: &gt;1 org → Tenant Switcher, exactly 1 org → Dashboard, 0 orgs → Onboarding Wizard</li></ul><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>Supabase Auth handles all token management. Frontend only triggers the auth method and handles session callbacks via <code>onAuthStateChange</code>. The login screen is the ONLY public page accessible pre-auth; all other routes redirect here.</p><hr><h2 id="screen-sign-up" tabindex="-1">Screen: Sign Up <a class="header-anchor" href="#screen-sign-up" aria-label="Permalink to &quot;Screen: Sign Up&quot;">​</a></h2><h3 id="route-1" tabindex="-1">Route <a class="header-anchor" href="#route-1" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/signup</code></p><h3 id="purpose-1" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-1" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Create a new user identity (no organization yet). Entry point for new SaaS users.</p><h3 id="data-source-1" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-1" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: Supabase Auth → <code>auth.users</code> → trigger <code>handle_new_user()</code> creates <code>User</code> + <code>UserPreference</code></li><li><strong>RLS Context</strong>: Pre-tenant (public). No tenant context.</li></ul><h3 id="fields-1" tabindex="-1">Fields <a class="header-anchor" href="#fields-1" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Name</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td>Full name; stored in <code>User</code> via trigger or post-signup</td></tr><tr><td>Email</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td>Must be unique in <code>auth.users</code></td></tr><tr><td>Password</td><td>password</td><td>User input</td><td>Yes</td><td>Yes</td><td>Min 8 chars; Supabase Auth hashing</td></tr><tr><td>Auth Provider</td><td>select</td><td>Config</td><td>No</td><td>N/A</td><td>OAuth provider buttons displayed instead of form when applicable</td></tr></tbody></table><h3 id="actions-crud-1" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-1" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[x] Create (auth identity)</li><li>[ ] Read</li><li>[ ] Update</li><li>[ ] Delete</li><li>[x] Special: Supabase Auth sign-up (<code>signUp</code>)</li></ul><h3 id="related-selectors-modals-1" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-1" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li>None</li></ul><h3 id="permissions-1" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-1" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>AUTH</code></li><li><strong>Minimum role permissions</strong>: None (public)</li><li><strong>Special rules</strong>: After signup, MUST redirect to Onboarding Wizard (first org creation)</li></ul><h3 id="navigation-1" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-1" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: Login (link from login page)</li><li><strong>Links to</strong>: Organization Onboarding Wizard (post-signup)</li></ul><h3 id="ux-pattern-1" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-1" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Form</p><h3 id="business-rules-validations-1" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-1" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>Email MUST NOT already exist in <code>auth.users</code> (Supabase enforces this)</li><li>Password MUST be &gt;= 8 characters</li><li><code>usr_auth_provider</code> in <code>User</code> table is set to the provider used (email, google, etc.)</li><li><code>UserPreference</code> auto-created via DB trigger with defaults (language: <code>es</code>, theme: <code>light</code>, color: <code>blue</code>)</li></ul><h3 id="notes-1" tabindex="-1">Notes <a class="header-anchor" href="#notes-1" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>After Supabase Auth signs up the user, the <code>handle_new_user()</code> DB trigger creates the <code>User</code> and <code>UserPreference</code> rows. The frontend then navigates to the Onboarding Wizard. If the user cancels onboarding, they can access it later from a prompt in the app shell.</p><hr><h2 id="screen-organization-onboarding-wizard" tabindex="-1">Screen: Organization Onboarding Wizard <a class="header-anchor" href="#screen-organization-onboarding-wizard" aria-label="Permalink to &quot;Screen: Organization Onboarding Wizard&quot;">​</a></h2><h3 id="route-2" tabindex="-1">Route <a class="header-anchor" href="#route-2" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/onboarding</code></p><h3 id="purpose-2" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-2" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>First-time tenant bootstrap: create organization, assign plan, create admin role, and link the creating user as the first admin employee.</p><h3 id="data-source-2" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-2" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>Organization</code>, <code>OrganizationPlan</code>, <code>OrganizationRole</code>, <code>OrganizationRoleMenu</code>, <code>EmployeeOrganization</code>, <code>Employee</code>, <code>Plan</code></li><li><strong>RLS Context</strong>: Authenticated but pre-tenant. This screen CREATES the tenant — no <code>app.current_tenant_id</code> yet.</li></ul><h3 id="fields-2" tabindex="-1">Fields <a class="header-anchor" href="#fields-2" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><p><strong>Step 1 — Organization Details:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Org Name</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td><code>Organization.org_name</code></td></tr><tr><td>Country</td><td>select</td><td>ISO 3166-1 alpha-2 list</td><td>Yes</td><td>Yes</td><td><code>Organization.org_country</code></td></tr><tr><td>Timezone</td><td>select</td><td>IANA TZ database</td><td>Yes</td><td>Yes</td><td><code>Organization.org_timezone</code></td></tr><tr><td>Primary Currency</td><td>select</td><td>ISO 4217</td><td>Yes</td><td>Yes</td><td><code>Organization.org_currency_primary</code></td></tr><tr><td>Secondary Currency</td><td>select</td><td>ISO 4217</td><td>No</td><td>Yes</td><td><code>Organization.org_currency_secondary</code></td></tr><tr><td>Operation Mode</td><td>select</td><td>1=Appointment, 2=Walk-in, 3=Hybrid</td><td>Yes</td><td>Yes</td><td><code>Organization.org_operation_mode</code></td></tr></tbody></table><p><strong>Step 2 — Plan Selection:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Plan</td><td>card select</td><td><code>Plan</code> (active only)</td><td>Yes</td><td>Yes</td><td>Shows name, description, limits, price</td></tr><tr><td>Billing Cycle</td><td>select</td><td>monthly / annual</td><td>Yes</td><td>Yes</td><td><code>OrganizationPlan.org_pln_billing_cycle</code></td></tr></tbody></table><p><strong>Step 3 — Admin Setup:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Admin First Name</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td><code>Employee.emp_first_name</code></td></tr><tr><td>Admin Last Name</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td><code>Employee.emp_last_name</code></td></tr><tr><td>Admin Phone</td><td>text</td><td>User input</td><td>Yes</td><td>Yes</td><td><code>Employee.emp_phone</code>, E.164 format</td></tr><tr><td>Identity Document Type</td><td>select</td><td><code>DocumentType</code> (filtered by country)</td><td>No</td><td>Yes</td><td><code>identity_document_type_id</code></td></tr><tr><td>Identity Document</td><td>text</td><td>User input</td><td>No</td><td>Yes</td><td><code>Employee.emp_identity_document</code></td></tr></tbody></table><p><strong>Step 4 — Confirmation:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Default Role Name</td><td>text</td><td>Auto-generated &quot;Admin&quot;</td><td>Yes</td><td>No</td><td><code>OrganizationRole.org_role_name</code> = &quot;Admin&quot;, <code>org_role_is_default</code> = true</td></tr></tbody></table><h3 id="actions-crud-2" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-2" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[x] Create (Organization, OrganizationPlan, OrganizationRole, EmployeeOrganization, Employee, OrganizationRoleMenu)</li><li>[ ] Read (<code>Plan</code> list for selection)</li><li>[ ] Update</li><li>[ ] Delete</li><li>[ ] Special: Transactional bootstrap — ALL creates MUST succeed or rollback as a unit</li></ul><h3 id="related-selectors-modals-2" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-2" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li><strong>Plan selector card</strong>: Shows <code>Plan</code> cards with name, description, limits, and pricing. Highlights selected.</li><li><strong>Country picker</strong>: ISO 3166-1 alpha-2 list.</li><li><strong>Timezone picker</strong>: IANA TZ list filtered by selected country.</li><li><strong>Currency picker</strong>: ISO 4217 list.</li><li><strong>DocumentType dropdown</strong>: Filtered by selected country.</li></ul><h3 id="permissions-2" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-2" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>AUTH</code></li><li><strong>Minimum role permissions</strong>: Authenticated (any signed-up user)</li><li><strong>Special rules</strong>: This is a one-time flow per user (until first org is created). User cannot have 0 orgs after initial creation unless all are deleted.</li></ul><h3 id="navigation-2" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-2" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: Sign Up (post-signup redirect)</li><li><strong>Links to</strong>: Tenant Switcher (post-completion)</li></ul><h3 id="ux-pattern-2" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-2" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Wizard (multi-step form with progress indicator, 4 steps, Back/Next/Submit navigation)</p><h3 id="business-rules-validations-2" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-2" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>Org name MUST be unique across the platform (enforced by application or unique constraint)</li><li>Country MUST be ISO 3166-1 alpha-2; timezone MUST be valid IANA</li><li>Plan selection is REQUIRED — no plan means no service</li><li>On submission, in a single DB transaction or edge function: <ol><li>INSERT <code>Organization</code></li><li>INSERT <code>OrganizationPlan</code></li><li>Find or create <code>Employee</code> for the current user</li><li>INSERT <code>OrganizationRole</code> with name &quot;Admin&quot;, <code>org_role_is_default = true</code></li><li>INSERT <code>EmployeeOrganization</code> linking employee + org + admin role</li><li>INSERT <code>OrganizationRoleMenu</code> for ALL active <code>SystemMenu</code> entries (Admin gets full CRUD on everything by default)</li></ol></li><li>After completion, set <code>app.current_tenant_id</code> to the new org and redirect to Tenant Switcher</li></ul><h3 id="notes-2" tabindex="-1">Notes <a class="header-anchor" href="#notes-2" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This is the most critical bootstrap flow in the system. Consider using a Supabase Edge Function to execute the transactional steps atomically. The wizard MUST handle the case where the user&#39;s <code>Employee</code> record already exists (global identity) — use <code>find_or_create_employee()</code> flow. If the user refreshes mid-wizard, preserve step state in URL params or session storage.</p><hr><h2 id="screen-tenant-switcher" tabindex="-1">Screen: Tenant Switcher <a class="header-anchor" href="#screen-tenant-switcher" aria-label="Permalink to &quot;Screen: Tenant Switcher&quot;">​</a></h2><h3 id="route-3" tabindex="-1">Route <a class="header-anchor" href="#route-3" aria-label="Permalink to &quot;Route&quot;">​</a></h3><p><code>/switch-tenant</code> (embedded in app shell layout, accessible from header)</p><h3 id="purpose-3" tabindex="-1">Purpose <a class="header-anchor" href="#purpose-3" aria-label="Permalink to &quot;Purpose&quot;">​</a></h3><p>Allow the authenticated user to switch between organizations they belong to. Sets <code>app.current_tenant_id</code> and <code>app.current_user_role_id</code> for all subsequent queries.</p><h3 id="data-source-3" tabindex="-1">Data Source <a class="header-anchor" href="#data-source-3" aria-label="Permalink to &quot;Data Source&quot;">​</a></h3><ul><li><strong>Table(s)</strong>: <code>EmployeeOrganization</code> (via <code>Employee</code> → <code>User</code>), <code>Organization</code></li><li><strong>RLS Context</strong>: Authenticated. Query filters: <code>employee -&gt; user_id = auth.uid()</code> AND <code>emp_org_status_code = 1</code>.</li></ul><h3 id="fields-3" tabindex="-1">Fields <a class="header-anchor" href="#fields-3" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Source</th><th>Required</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td>Organization Name</td><td>text (display)</td><td><code>Organization.org_name</code></td><td>N/A</td><td>N/A</td><td>Displayed in dropdown</td></tr><tr><td>Current Indicator</td><td>badge</td><td>Boolean</td><td>N/A</td><td>N/A</td><td>Highlight currently active org</td></tr><tr><td>Role Name</td><td>text (display)</td><td><code>OrganizationRole.org_role_name</code></td><td>N/A</td><td>N/A</td><td>Displayed as subtitle</td></tr></tbody></table><h3 id="actions-crud-3" tabindex="-1">Actions / CRUD <a class="header-anchor" href="#actions-crud-3" aria-label="Permalink to &quot;Actions / CRUD&quot;">​</a></h3><ul><li>[ ] Create</li><li>[x] Read (list accessible orgs)</li><li>[ ] Update</li><li>[ ] Delete</li><li>[x] Special: Switch tenant — sets <code>app.current_tenant_id</code> and <code>app.current_user_role_id</code> in local state/middleware</li></ul><h3 id="related-selectors-modals-3" tabindex="-1">Related Selectors / Modals <a class="header-anchor" href="#related-selectors-modals-3" aria-label="Permalink to &quot;Related Selectors / Modals&quot;">​</a></h3><ul><li>None (simple dropdown or sidebar switch)</li></ul><h3 id="permissions-3" tabindex="-1">Permissions <a class="header-anchor" href="#permissions-3" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><ul><li><strong>Module code</strong>: <code>AUTH</code></li><li><strong>Minimum role permissions</strong>: Authenticated + active EmployeeOrganization (status_code = 1)</li><li><strong>Special rules</strong>: If user has exactly 1 org, auto-select on login (skip dropdown)</li></ul><h3 id="navigation-3" tabindex="-1">Navigation <a class="header-anchor" href="#navigation-3" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li><strong>Parent</strong>: App Shell (header/sidebar)</li><li><strong>Links to</strong>: All tenant-scoped screens (indirectly — switching changes data context)</li></ul><h3 id="ux-pattern-3" tabindex="-1">UX Pattern <a class="header-anchor" href="#ux-pattern-3" aria-label="Permalink to &quot;UX Pattern&quot;">​</a></h3><p>Dropdown / Sidebar selector</p><h3 id="business-rules-validations-3" tabindex="-1">Business Rules / Validations <a class="header-anchor" href="#business-rules-validations-3" aria-label="Permalink to &quot;Business Rules / Validations&quot;">​</a></h3><ul><li>MUST show ALL orgs where <code>EmployeeOrganization.emp_org_status_code = 1</code> for the current user</li><li>On org selection: <ol><li>Set <code>app.current_tenant_id</code> to selected <code>Organization.id</code></li><li>Set <code>app.current_user_role_id</code> to the user&#39;s <code>OrganizationRole.id</code> for that org</li><li>Re-fetch navigation tree (<code>SystemMenu</code> × <code>PlanMenu</code> × <code>OrganizationRoleMenu</code>)</li><li>Redirect to Dashboard (or stay on current page if accessible in new org context)</li></ol></li><li>If current tenant becomes inactive or user&#39;s role is revoked, MUST auto-switch to next available org or show empty state</li></ul><h3 id="notes-3" tabindex="-1">Notes <a class="header-anchor" href="#notes-3" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><p>This screen is the architectural keystone of the multi-tenant system. The <code>app.current_tenant_id</code> and <code>app.current_user_role_id</code> MUST be injected into every Supabase API call (as session variables or headers). Implementation: store in React context, pass as Supabase session variables via <code>supabase.rpc()</code> or custom headers. Must be prominent in the app header — never hidden in sub-menus.</p>',103)])])}const g=t(r,[["render",d]]);export{p as __pageData,g as default};
